INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(151900, 0, 1519, 0, 0, 0, 'Stormwind City', 'Stormwind City is the capital of the human kingdom of Stormwind and the chief stronghold of the Alliance, raised in white stone on the northwest coast, north of Elwynn Forest. The old city was reduced to ashes when the orcish Horde sacked it in the First War and King Llane was slain. It rose again through the labor of the Stonemasons'' Guild, aided by the Church of the Holy Light and by King Terenas of Lordaeron, but the nobles never paid the masons what they were owed, and those cheated builders became the Defias Brotherhood. Canals now divide the city into districts: the busy Trade District, Cathedral Square beneath the Cathedral of Light, the poor streets of Old Town, the Mage Quarter, and the Dwarven District with its tram to Ironforge. The Stockade holds the kingdom''s prisoners. King Varian Wrynn sits on the throne again after long years lost, the noblewoman Katrana Prestor has been exposed as the black dragon Onyxia, and the former regent, Highlord Bolvar Fordragon, has fallen at the Wrathgate in Northrend.', 'warcraft.wiki.gg/wiki/Stormwind_City (founding, First War, rebuilding by Stonemasons, Church of Light and Terenas, districts, Deeprun Tram); quest 389 description (masons cheated by the nobles); quest 373 (City Hall, Cathedral Square); npc_text 13593 (Varian: reclaim my throne); quest 6403 description (Prestor is Onyxia); quest 13347 (Bolvar''s fall)'),
(151901, 1, 1519, 1, 0, 0, 'Valley of Heroes', 'The Valley of Heroes is the southern approach to Stormwind, where a stone bridge crosses the moat to the city gates. Along the road stand five statues of the leaders of the Alliance Expedition that marched through the Dark Portal into Draenor: Archmage Khadgar, General Turalyon, Ranger Captain Alleria Windrunner, Danath Trollbane and the gryphon rider Kurdran Wildhammer. Each plaque calls its hero presumed deceased and carries a farewell from a comrade or kinsman, from Antonidas and Uther to Sylvanas Windrunner, though word from Outland says some of them still live. Field Marshal Afrasiabi and Major Mattingly keep watch here, and it is here that the Field Marshal calls the city to rally around the champions who slew Nefarian.', 'warcraft.wiki.gg/wiki/Valley_of_Heroes (pre-Cataclysm: bridge, moat, five statues of the Alliance Expedition); gameobjects 25329-25333 and page_text 287-291 (plaques, presumed deceased, dedications); DB: Khadgar 18166, Force Commander Danath Trollbane 16819, Kurdran Wildhammer 21330 spawned on map 530 (Outland); DB spawns: Field Marshal Afrasiabi 14721, Major Mattingly 14394 by the gate; quest 7782 and creature_text 14721 (Nefarian slain, rally around your champion); tools/posarea.py: Afrasiabi, Mattingly, Marcus Jonathan, Jorgen and Squire Rowe spawns all resolve to area 1617'),
(151902, 1, 1519, 2, 0, 0, 'Stormwind Harbor', 'Stormwind Harbor spreads along the Great Sea below the city''s northwestern quarter, a fortified port of tiered docks, cannon emplacements and steam tanks. Here, at the start of the war against the Lich King, Scourge forces struck at the city, and King Varian Wrynn and Highlord Bolvar Fordragon directed the defense from atop the harbor walls. Now the port feeds that war. The steam-powered Kraken carries soldiers to Valiance Keep in the Borean Tundra, while The Bravery sails for Auberdine in Darkshore from a dock watched by night elf sentinels. Not every ship is so ready: the captain of the Assurance complains that his vessel has somehow been overrun with bugs.', 'warcraft.wiki.gg/wiki/Stormwind_Harbor (added 3.0.2, Scourge attack, Varian and Bolvar on the walls, Kraken and Bravery routes, cannons and steam tanks); transports table: The Kraken (Valiance Keep) and The Bravery (Auberdine); npc_text for Leesha Tannerby 26548 and Nayura 28650; DB spawns: Auberdine Sentinel x4, Steam Tank Engineer, Stormwind Cannoneer in the harbor; npc_text for Captain Paul Carver 29287 (The Assurance inundated with bugs)'),
(151903, 2, 1519, 1, 1, 0, 'King Varian Wrynn', 'Varian Wrynn was a boy when the orcs sacked Stormwind and King Llane, his father, was assassinated. Raised in exile in Lordaeron, he returned to rule the rebuilt city, married Tiffin and fathered a son, only to lose his queen in the riot that grew out of the nobles'' quarrel with the Stonemasons. Sailing in secret to meet Jaina Proudmoore at Theramore, he was abducted by the Defias. Stripped of his memory, he fought as a gladiator called Lo''Gosh before reclaiming his name and his throne, and Lady Prestor was unmasked as Onyxia on his return. A fierce and grieving king, he blames the Horde for the Wrathgate and puts little faith in peace.', 'warcraft.wiki.gg/wiki/Varian_Wrynn (youth, exile, Tiffin, abduction, Lo''Gosh, Onyxia unmasked, Wrathgate); npc_text 13593; quest 1250 description (king taken on his way to Theramore to meet Jaina); quest 13347 reward text; quest 13377 reward text (Peace? Useless)'),
(151904, 2, 1519, 2, 1, 0, 'Prince Anduin Wrynn', 'Prince Anduin Wrynn, son of King Varian and the late Queen Tiffin, was named for the hero Anduin Lothar and for his grandfather Llane. When his father vanished, Lady Katrana Prestor urged the council to crown the boy so that order might be kept, and he reigned in name while Highlord Bolvar Fordragon governed as regent. The deception ended when Prestor was revealed as Onyxia, who carried the boy off to her lair before he was rescued. Now the prince stands beside the throne once more, a quiet and thoughtful boy where his father is fierce.', 'warcraft.wiki.gg/wiki/Anduin_Wrynn (birth, naming, crowning under Bolvar''s regency at Prestor''s urging, kidnapping by Onyxia, personality, interest in the Light); DB spawn: Anduin Wrynn 1747 beside King Varian in the keep; npc_text 16641'),
(151905, 2, 1519, 3, 1, 0, 'Highlord Bolvar Fordragon', 'Highlord Bolvar Fordragon, a paladin of the Silver Hand, ruled Stormwind as regent for young Anduin while King Varian was lost. Lady Prestor stood at his side, and only after she was unmasked did it become known that a medallion she had placed around his neck, the Dragon''s Eye, had held his mind and body captive. When Varian returned, Bolvar led the Alliance north against the Lich King. At Angrathar the Wrathgate the Forsaken traitor Putress loosed a plague upon Alliance and Horde alike, and the red dragonflight burned the field clean. Bolvar''s body was never found. His shield was carried home to the king, who blamed himself for the loss.', 'warcraft.wiki.gg/wiki/Bolvar_Fordragon (Silver Hand, regent, Drakefire Amulet, Valiance Expedition, Wrathgate); quest 6403 description and reward text (the Highlord a puppet; medallion held my mind and body captive); quest 12499 (Highlord Bolvar Fordragon at Fordragon Hold); quest 13347 description and completion text (This is my fault); quest 13370 description (Putress)'),
(151906, 2, 1519, 4, 1, 0, 'Master Mathias Shaw', 'Master Mathias Shaw leads SI:7, the kingdom''s intelligence service, from the barracks in Old Town. Few shady or underhanded dealings in the city escape his notice, and he likes to call himself the master of all assassins. It was Shaw who recognized the quiet visitor to Bazil Thredd''s cell as the assassin Marzon and traced him to Lord Gregor Lescovar, and his agents keep watch on the Defias in Westfall. When five of his best field agents went to the Eastern Plaguelands after the lost ranger lord Nathanos Marris, only one came back, to die in his sleep days later. With Ravenholdt refusing aid, Shaw had to seek outside help to learn their fate.', 'npc_text 5994 (SI:7 headquarters); quest 393 description and reward text; quest 394 reward text (master of all assassins); quest 6182 and 6183 descriptions; quests 2359, 2360 (Agent Kearnen in Westfall); warcraft.wiki.gg/wiki/Mathias_Shaw'),
(151907, 2, 1519, 5, 1, 0, 'Archbishop Benedictus', 'Archbishop Benedictus leads the Church of the Holy Light from the Cathedral of Light in Cathedral Square. In his youth he studied under Archbishop Alonsus Faol, the benevolent patron who raised great sums to rebuild Stormwind after the Second War, and he helped the Church raise the Cathedral of Light that stands as a monument to his teacher. Benedictus succeeded his teacher at the head of the Church. From his cathedral he keeps watch on the Scourge even in distant lands: he has sent champions into Razorfen Downs to break the pact between the quilboar there and the lich Amnennar the Coldbringer. Tainted Eyes of Paleth, crafted long ago by human priests, are brought to him to be cleansed.', 'warcraft.wiki.gg/wiki/Archbishop_Benedictus (pupil of Faol, built the Cathedral, succeeded him); warcraft.wiki.gg/wiki/Alonsus_Faol; page_text 2291 (Faol plaque); quest 3636 description; quest 293 description and reward text'),
(151908, 2, 1519, 6, 1, 0, 'Baros Alexston', 'Baros Alexston, City Architect of Stormwind, keeps his office at City Hall in Cathedral Square. He grew up working his family''s farm in Westfall, a homestead since burned and seized by thieves. As a young man he was a member of the Stonemasons'' Guild with Edwin VanCleef, rebuilding the city after the war. When the nobles refused to pay, VanCleef led a riot and left the city swearing revenge, while Baros accepted the post of city architect and stayed in Stormwind''s service. He still calls his old colleague an idealist and a romantic consumed by revenge, yet admits he cannot entirely blame him. Mathias Shaw of SI:7 owes him a favor.', 'quest 373 description and reward text; quest 389 description; quest 399 description; quest 393 description (Shaw owes me a favor); creature_template 1646 subname City Architect; warcraft.wiki.gg/wiki/Baros_Alexston (accepted the city architect position rather than join VanCleef)'),
(151909, 2, 1519, 7, 1, 0, 'Elling Trias', 'Elling Trias runs Trias'' Cheese in the Trade District with his wife Elaine and his son Ben, and will happily offer a taste of Trias cheddar or a block of Darnassian bleu. Those who know better come to him for something else. Behind the counter lies a quiet web of friends and contacts that reaches from Stormwind Keep to Darkshire, Menethil Harbor and Theramore, and when the kingdom''s own agents cannot act, Trias can. He has little love for Mathias Shaw, who turns to him only when he must, and he prefers his justice swift and off the record. Those who trouble his friends, he says, rarely stay healthy for long.', 'quest 1242 request text (cheddar and Darnassian bleu); creature_template 483 Elaine Trias, 4981 Ben Trias; quests 1243, 1248, 1264, 2745 (contacts Backus, Mikhail, Samaul, Tyrion); quest 350 description and reward text; quest 2745 description; quest 434 completion text; warcraft.wiki.gg/wiki/Elling_Trias'),
(151910, 2, 1519, 8, 1, 0, 'Zardeth of the Black Claw', 'In the cellar of the Slaughtered Lamb tavern in the Mage Quarter, Zardeth of the Black Claw speaks for the warlocks of Stormwind, served by a demon named Zggi. Their gatherings drew the ire of Lord Baurles K. Wishock of the House of Nobles, who lobbied for a full investigation, though Zardeth notes that the lord spends his nights upstairs running up a bill he never pays. Zardeth answered him with a special Black Claw stout, brewed from a rare flower of Darkshire and a root from the Wetlands, and the warlocks have practiced their ways undisturbed ever since. Of late even the head of the dragon Onyxia has found its way down to his cellar, much to his puzzlement.', 'quests 335, 336, 397 (descriptions and reward texts); quest 24428 description and reward text (basement of the Slaughtered Lamb); creature_template 1733 Zggi, Zardeth''s Minion, creature type demon; warcraft.wiki.gg/wiki/Zardeth_of_the_Black_Claw (Slaughtered Lamb, Mage Quarter)'),
(151911, 3, 1519, 1, 1, 0, 'The Missing King', 'It began with a whisper. Thomas, an altar boy, quietly sought out capable strangers for Bishop DeLavey, who confided that a diplomat bound for Theramore to meet Jaina Proudmoore had never arrived, and that the Defias were somehow involved. DeLavey''s old friend Jorgen, fishing in the Valley of Heroes, passed the matter to the cheesemonger Elling Trias. A Defias docket found at Addle''s Stead in Duskwood named a brawler called Fist, Dashel Stonefist of Old Town, who after a beating gave up an inside man from Menethil known as Slim. Cornered in Menethil''s tavern, Tapoke Jahn confessed: the Defias had taken no mere diplomat but the king himself, with help from a partner greater than they, and their man Hendel had been placed aboard the royal ship. Hendel proved to be a soldier of the Theramore garrison. He was brought down in Dustwallow Marsh, and Lady Proudmoore quietly thanked those who had uncovered the plot.', 'quests 1274, 1241, 1242, 1243, 1244, 1245, 1246, 1447, 1247, 1248, 1249, 1250, 1264, 1265, 1266, 1324, 1267 (descriptions and reward texts); creature 4959 Jorgen spawned in the Valley of Heroes'),
(151912, 3, 1519, 2, 1, 0, 'VanCleef''s Last Plot', 'Even in death Edwin VanCleef had one more scheme. An unsent letter on his body, addressed to the City Architect Baros Alexston, led Baros to recall their days as Stonemasons and to point toward Bazil Thredd, VanCleef''s lieutenant, held in the Stockade. Thredd was slain amid a riot in the prison, but Warden Thelwater revealed that a quiet stranger calling himself Maelik had lately visited him often. Mathias Shaw knew the description: the assassin Marzon, in the pay of Lord Gregor Lescovar. With VanCleef and Thredd dead, no court would touch so well connected a noble, so Shaw reluctantly sent word to Elling Trias. Trias''s friend Tyrion, a gnome who had been watching Lescovar for weeks, used a disguised Spybot to draw the lord into the castle garden to meet Marzon. Once their talk of the Defias was overheard, both were cut down, and Baros''s report on the Brotherhood went to the king.', 'quests 373, 389, 391, 392, 393, 350, 2745, 2746, 434, 394, 395, 396 (descriptions and reward texts); creature_text 1754, 1755, 7766, 8856; DB spawns: Lord Gregor Lescovar 1754 and Tyrion 7766 at Stormwind Keep'),
(151913, 3, 1519, 3, 1, 0, 'The Blightcaller', 'Nathanos Marris was the first and last of the human ranger lords, the only human ever allowed to train under the high elves, and a disciple of Sylvanas Windrunner. He was believed to have died defending Lordaeron, though his body was never found. When strange Forsaken activity was reported in the Eastern Plaguelands, SI:7 sent five of its best agents to investigate. One came back, able to utter only two words, Nathanos and Blightcaller, before dying in his sleep. At King Varian''s word Mathias Shaw sent volunteers to Flint Shadowmore at Chillwind Camp, and the insignias of the lost agents were recovered in the east. The truth shook the king: the Blightcaller was Nathanos himself, now champion of the Banshee Queen. Varian ordered an army raised to destroy him, and mourned that his people seem cursed to lose their greatest heroes.', 'quests 6182, 6183, 6184, 6185, 6186, 6187 (descriptions and reward texts); creature_queststarter: 29611 King Varian Wrynn starts 6182'),
(151914, 3, 1519, 4, 1, 0, 'Dragons at Court', 'For years the House of Wrynn was steered from the shadows. Lady Katrana Prestor, a high noble and royal councilor, urged the crowning of the boy Anduin and stood at the regent''s side, while a medallion she had placed upon Bolvar Fordragon held him captive. She was Onyxia, brood of Deathwing and twin of Nefarian, the tyrant of Blackrock Spire. Her masquerade ended in Stormwind Keep, at the cost of Marshal Reginald Windsor''s life, and she fled with the young prince to her lair in the Wyrmbog of Dustwallow Marsh. Her brother fared no better at the hands of the Alliance. When Nefarian''s head was carried back to Stormwind, King Varian hailed a victory the like of which the Alliance had not known in years, and Field Marshal Afrasiabi called the city to rally around its champions in the Valley of Heroes.', 'quest 6403 description and reward text (Prestor is Onyxia, twin of Nefarian, the Highlord a puppet, Windsor''s sacrifice); quest 6501 description (lair in the Wyrmbog); warcraft.wiki.gg/wiki/Katrana_Prestor (councilor, Anduin crowned at her urging, Windsor killed, Anduin taken to her lair); quests 7781, 7782 and creature_text 14721'),
(151915, 3, 1519, 5, 1, 0, 'The Wrathgate and the King''s Wrath', 'When Bolvar Fordragon fell at the Wrathgate, the dragon queen Alexstrasza sent his shield home to King Varian with a message: all is not lost, and from the ashes of the fallen a force will rise to purge the evil from the world. Varian took it as a call to purge the Horde. At Jaina Proudmoore''s urging he first allowed a diplomatic mission, and Jaina went to Orgrimmar to hear Thrall out. The Warchief swore the Horde had no part in Putress''s cowardly attack, that it too had lost heroes, and that it would defend itself if provoked. Learning that the Horde had lost the Undercity, Varian seized the moment. Broll Bearmantle and Valeera Sanguinar already waited outside the ruins, Jaina opened a portal from Stormwind Keep, and the king led the Alliance in to bring Putress to justice. He came home convinced that peace with the Horde had won his people nothing.', 'quests 13347, 13369, 13370, 13371, 13377 (descriptions and reward texts); creature_text 32346; npc_text 14131 (Jaina: avoid another war at all costs); warcraft.wiki.gg/wiki/Varian_Wrynn (Wrath section)'),
(151916, 3, 1519, 6, 1, 0, 'Where Kings Walk', 'When the Knights of the Ebon Blade broke from the Lich King, Highlord Darion Mograine sent those death knights who had once been heroes of the Alliance to Stormwind as envoys, bearing a letter from Tirion Fordring. Their welcome was bitter. Guards, some of whom had lost their families to the Scourge, pelted them with rotten fruit, spat at them and cried murderer and monster as they made their way to the keep. King Varian declared that only the word of Tirion, one of the greatest paladins ever to live, kept the envoy from becoming a stain upon his floor. Yet he honored his old friend''s letter. Blood and honor, he answered, and he pledged that Stormwind would fight alongside the Ebon Blade against the Scourge and the Lich King.', 'quest 13188 description, completion text and reward text; creature_text 68 and 1976 groups 2 to 5 (rotten fruit, spitting, Monster, My family was wiped out by the Scourge); warcraft.wiki.gg/wiki/Stormwind_City (Varian ordered death knights treated with respect after Tirion''s letter); spell_area 58530 (Alliance, quest 13165 done until 13188 done) and spell_script_names 58533 spell_chapter5_return_to_capital, which makes guards 68, 1756 and 1976 use text groups 2 to 5 on death knights');
